Mean[Flatten[data]] // N

img = ExampleData[{"TestImage", "Lena"}];
gray = ColorConvert[img, "Grayscale"];
lab = ColorConvert[img, "LAB"];

img = ExampleData[{"TestImage", "Boat"}];
bg = GaussianFilter[img, 25];
ImageAdjust@ImageSubtract[img, bg]

img = ExampleData[{"TestImage", "Lena"}];
mask = Image[DiskMatrix[128, 256]];
ImageMultiply[img, ImageResize[mask, ImageDimensions[img]]]

a = ExampleData[{"TestImage", "Boat"}];
b = GaussianFilter[a, 2];
ImageAdjust@ImageDifference[a, b]

bg = ExampleData[{"TestImage", "House"}];
ImageCompose[bg, {Rasterize[Style["DRAFT", 60, Red], Background -> None], 0.5},
  Scaled[{0.5, 0.5}]]

img = ExampleData[{"TestImage", "Mandrill"}];
{h, s, b} = ColorSeparate[img, "HSB"];
ColorCombine[{h, ImageAdjust[s, {0.5, 0}], b}, "HSB"]

